import {RULES} from './learning-model.js?v=20261102-learning2';
export const METHOD_REVIEWED='2026-11-02';
export const METHOD_SOURCES=[
 ['Yang et al. (2021)','Testing (quizzing) boosts classroom learning: A systematic and meta-analytic review','https://pubmed.ncbi.nlm.nih.gov/33683913/','Aktives Abrufen unterstützt das Behalten; die Wirkung hängt unter anderem von Aufgabe, Feedback und Prüfung ab.','Retrieval practice supports retention; effects depend on tasks, feedback and assessment.'],
 ['Latimier, Peyre & Ramus (2021)','A Meta-Analytic Review of the Benefit of Spacing out Retrieval Practice Episodes on Retention','https://doi.org/10.1007/s10648-020-09572-8','Verteiltes Abrufen ist besser belegt als eine bestimmte Folge von Intervallen.','Evidence supports spaced retrieval, not one particular interval sequence.'],
 ['Rawson & Dunlosky (2022)','Successive Relearning: An Underexplored but Potent Technique for Obtaining and Maintaining Knowledge','https://doi.org/10.1177/09637214221100484','Erfolgreiches Erinnern in getrennten Sitzungen unterscheidet sich vom kurzfristigen Wiederholen.','Successful retrieval across spaced sessions differs from short-term repetition.'],
 ['Butler & Roediger (2008)','Feedback enhances the positive effects and reduces the negative effects of multiple-choice testing','https://pubmed.ncbi.nlm.nih.gov/18491500/','Korrekturfeedback hilft auch, falsche Auswahlantworten nicht mitzulernen.','Corrective feedback also helps prevent learning incorrect distractors.'],
 ['van den Broek et al. (2023)','Optimizing Multiple-Choice Questions for Retrieval Practice: Delayed Display of Answer Alternatives Enhances Vocabulary Learning','https://doi.org/10.1037/edu0000810','Zunächst verborgene Optionen unterstützten das Vokabellernen unter den untersuchten Bedingungen.','Initially hidden options supported vocabulary learning under the conditions studied.'],
 ['Brom et al. (2026)',"Retrieval Practice in the Wild: Comparing Different Multiple-Choice Question Formats on a Children's TV Gaming Site",'https://doi.org/10.1002/acp.70217','Selbstbestimmtes Einblenden zeigte kleine Vorteile bei der Ausdauer, aber keinen Unterschied im gemessenen kurzfristigen Lernzuwachs.','Learner-paced revealing showed small benefits for persistence, but no difference in measured short-term learning gains.'],
 ['Ruitenburg et al. (2026)','A Meta-Analysis of the Effectiveness and Boundary Conditions of Retrieval Practice, Distributed Practice, and Interleaved Practice in Authentic School Classrooms','https://doi.org/10.1007/s10648-026-10225-5','Die Wirkung dieser Lernprinzipien hängt vom Lernmaterial und Unterrichtskontext ab.','Effects of these learning principles depend on material and classroom context.']
];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderLearningMethod(english=false){
 const c=(de,en)=>english?en:de,ref=n=>` <a href="#lernmethode/method-source-${n+1}">[${n+1}]<span class="sr"> ${c('Quelle','Source')}: ${esc(METHOD_SOURCES[n][0])}</span></a>`;
 const sections=[
 ['goal',c('Was du hier lernst','What you learn'),c('Du lernst Vogelnamen und Quick Find Codes, einschließlich belegter akzeptierter Varianten. Fotos unterstützen die Zuordnung. Die Aufgaben prüfen keine Bestimmung anhand unbekannter Vogelbilder.','You learn bird names and Quick Find Codes, including documented accepted variants. Photos support the association. These tasks do not assess identification from unfamiliar bird photographs.')],
 ['daily',c('Deine Tagesrunde','Your daily round'),c(`Zuerst kommen fällige Wiederholungen, danach neue Lernziele: höchstens ${RULES.round} Fragen pro Runde und ${RULES.newPerDay} neue Lernziele pro Kalendertag, gemeinsam für alle Sprachen und Methoden. Eine Art mit Ausgangssprache und Antwortname oder Code ist ein Lernziel. Neue Namenspaare werden kurz vorgestellt; später folgt die erste Übung. Vorstellung und Erstübung bestätigen noch kein langfristiges Erinnern.`,`Due reviews come first, then new learning targets: at most ${RULES.round} questions per round and ${RULES.newPerDay} new targets per calendar day across languages and methods. A target is a species with a question language and an answer name or code. New pairs are introduced briefly before their first practice. Introduction and initial practice do not confirm long-term retention.`)+`</p><p>`+c('Region, Jahreszeit und Artenfilter bestimmen neue Lernziele. Bereits begonnene bleiben unabhängig davon wiederholbar, auch nach Ablauf einer aktuellen Besonderheit. Im freien Üben kannst du die Arten und den Umfang selbst wählen und bewusst mehr Neues beginnen.','Region, season and species filters determine new targets. Started targets remain available for review, even after a current addition expires. Free practice lets you choose species and session size and deliberately start more new targets.')],
 ['formats',c('Die Antwortmethoden','Answer methods'),c('„Erst überlegen“ ist der Standard: Versuche zunächst, dich zu erinnern, und zeige dann die Antwortmöglichkeiten an. Es gibt keine Wartezeit. Das Anklicken einer Antwort prüft Wiedererkennen, auch wenn du zuvor selbst überlegt hast. Direkte Auswahl zeigt die Optionen sofort; Texteingabe prüft freien Abruf. Karteikarten verwenden deine Selbsteinschätzung. Tippen bleibt freiwillig. „Weiß ich nicht“ zeigt die Auflösung.','“Think first” is the default: try to remember, then reveal the answer options when ready. There is no waiting time. Selecting an option assesses recognition, even after thinking first. Direct choice shows options immediately; typing assesses recall. Flashcards use self-assessment. Typing remains optional. “I don’t know” reveals the answer.')+ref(4)+ref(5)],
 ['feedback',c('Fehler, Hinweise und Wiederholungen','Errors, hints and reviews'),c(`Nach jeder Antwort siehst du die richtige Lösung. Nach Fehlern oder richtigen Antworten mit Hinweis gibt es höchstens ${RULES.maxRetries} Zusatzversuche, möglichst nach drei anderen Fragen. Ohne Abstand entfällt der Zusatzversuch. Diese kurzfristigen Übungen sind keine zeitversetzten Bestätigungen. Hinweise löschen deine Bestätigungen nicht, erhöhen sie aber auch nicht.`,`Every answer is followed by the correct solution. Errors and correct hinted answers can receive at most ${RULES.maxRetries} extra attempts, preferably after three other questions. Without spacing, no extra attempt is added. These short-term exercises are not spaced confirmations. Hints neither erase nor increase your confirmations.`)+ref(3)],
 ['progress',c('Was dein Lernstand bedeutet','What your progress means'),c(`„Fällig“ bedeutet: Der geplante Zeitpunkt zum erneuten Üben ist erreicht. „Sicher wiedererkannt“ gilt für Auswahlantworten, „Sicher abgerufen“ für Texteingabe; Karteikarten heißen „Nach eigener Einschätzung sicher“. Jeder Status benötigt ${RULES.confirmations} aufeinanderfolgende richtige, fällige Wiederholungen ohne Hinweis mit mindestens ${RULES.minGap/3600000} Stunden seit dem letzten bewerteten Versuch. Ausgangssprache, Antwortziel und Methodenfamilie haben getrennte Nachweise.`,`“Due” means the scheduled practice time has arrived. “Securely recognised” applies to selected answers, “Securely recalled” to typed answers; flashcards show “Secure by self-assessment”. Each status requires ${RULES.confirmations} consecutive correct due reviews without a hint, at least ${RULES.minGap/3600000} hours after the previous graded attempt. Question language, answer target and method family have separate evidence.`)+ref(1)+ref(2)+`</p><p>`+c(`Nach erfolgreicher Erstübung folgt die nächste Wiederholung nach einem Tag. Die Intervalle sind ${RULES.intervals.join(', ')} Tage, danach höchstens 60 Tage. Ein Fehler setzt die Bestätigungsserie zurück, reduziert die Intervallstufe um eins und macht das Ziel nach zehn Minuten wieder fällig. Ein richtiger Hinweisversuch wird spätestens am Folgetag wiederholt; frühere Termine bleiben erhalten. Richtige vorgezogene Übungen verschieben Termine nicht. Auch beim freien Üben können tatsächlich fällige, ausreichend verteilte Abfragen zählen.`,`Successful initial practice schedules the next review in one day. Intervals are ${RULES.intervals.join(', ')} days, capped at 60 days. An error resets the confirmation sequence, reduces the interval stage by one and makes the target due in ten minutes. A correct hinted answer is reviewed within one day; earlier dates remain. Correct early practice does not postpone reviews. Due, sufficiently spaced retrieval can also count in free practice.`)+`</p><p>`+c('Frühere Lernwerte bleiben erhalten. Alte als „beherrscht“ geführte Ziele werden als historischer Lernstand angezeigt und mit den neuen Regeln bestätigt. Ein Methodenwechsel überträgt keine Sicherheit vom Wiedererkennen auf freien Abruf.','Earlier progress is preserved. Previously “mastered” targets are shown as historical progress and confirmed under the new rules. Changing methods does not transfer recognition evidence to recall.')],
 ['research',c('Wissenschaft und unsere Produktregeln','Research and our product rules'),c('Aktives Abrufen, Rückmeldung und zeitlich verteiltes Wiederholen sind wissenschaftlich gut begründet. Die Wirksamkeit hängt jedoch von Aufgabe, Lernziel und Kontext ab. Nicht jede Methode ist unter allen Bedingungen überlegen.','Retrieval practice, feedback and spaced practice have strong research support. Effects depend on task, learning goal and context. No method is superior under every condition.')+ref(0)+ref(6)+`</p><p>`+c(`Unsere Grenzen von ${RULES.round} Fragen, ${RULES.newPerDay} neuen Zielen, ${RULES.confirmations} Bestätigungen, 24 Stunden Mindestabstand, die konkreten Intervalle und die Zahl der Zusatzversuche sind nachvollziehbare Produktentscheidungen, keine wissenschaftlich optimalen Schwellen. Die Studien haben BirdNames DE selbst nicht evaluiert. Insbesondere ist „Erst überlegen“ keine Garantie für einen höheren Lernerfolg.`,`Our limits of ${RULES.round} questions, ${RULES.newPerDay} new targets, ${RULES.confirmations} confirmations, a 24-hour minimum gap, specific intervals and extra attempts are product decisions, not scientifically optimal thresholds. These studies did not evaluate BirdNames DE itself. In particular, “Think first” does not guarantee better learning.`)]
 ];
 return `<h1>${c('Lernmethode','Learning method')}</h1><div class="panel information-page"><p class="intro">${c('Namen kennenlernen, selbst erinnern, Rückmeldung bekommen und mit Abstand wiederholen.','Learn names, try to remember, get feedback and review after a delay.')}</p><p class="muted">${c('Quellen geprüft am 2. November 2026.','Sources reviewed on 2 November 2026.')}</p>${sections.map(([id,title,body])=>`<section aria-labelledby="method-${id}"><h2 id="method-${id}">${title}</h2><p>${body}</p></section>`).join('')}<section aria-labelledby="method-sources"><h2 id="method-sources">${c('Wissenschaftliche Quellen','Scientific sources')}</h2><ol>${METHOD_SOURCES.map(([authors,title,url,de,en],i)=>`<li id="method-source-${i+1}" tabindex="-1"><a href="${url}" target="_blank" rel="noopener noreferrer">${esc(authors)}: <cite>${esc(title)}</cite> ↗</a><p>${esc(english?en:de)}</p></li>`).join('')}</ol></section><a class="button-link" href="#lernen">${c('Zurück zum Lernen','Back to learning')}</a></div>`;
}
